import numpy as np

def simulate_arch1(omega, alpha, n, seed):
    z = np.random.default_rng(seed).standard_normal(n)
    r = np.empty(n); s2 = np.empty(n)
    s2[0] = omega / (1 - alpha)
    for t in range(n):
        if t > 0:
            s2[t] = omega + alpha * r[t - 1] ** 2
        r[t] = np.sqrt(s2[t]) * z[t]
    return r

def arch1_uncond_var(omega, alpha):
    if alpha >= 1:
        raise ValueError("no unconditional variance for alpha >= 1")
    return omega / (1 - alpha)

import math

def arch1_kurtosis(alpha):
    if 3 * alpha ** 2 >= 1:
        return math.inf
    return 3 * (1 - alpha ** 2) / (1 - 3 * alpha ** 2)
